def build_agent(sandbox):
    # Define blocks to create overhang
    blocks = []
    for i in range(10):
        # Block i is placed with increasing x offset from the table edge
        x = -0.5 + i * 0.15  # Start from x = -0.5, increase by 0.15 per block
        y = 0.11 + i * 0.15  # Increase y to create a stable stack
        block = sandbox.add_block(x, y, 1.0, 0.2, density=1.0)
        blocks.append(block)
    return blocks

def agent_action(sandbox, agent_body, step_count):
    blocks = build_agent(sandbox)  # Ensure blocks are accessible
    for block in blocks:
        # Apply downward force if block is moving upward
        if block.linearVelocity.y > 0:
            sandbox.ApplyForceToCenter(block, (0, -100.0), True)
